local function playerOf(inst)
    if typeof(inst) ~= "Instance" then
        return nil
    end
    if prop(inst, "ClassName") == "Player" then
        return inst
    end
    local n, hops = inst, 0
    while n and hops < 8 do
        local ok, p = pcall(Players.GetPlayerFromCharacter, Players, n)
        if ok and p then
            return p
        end
        n = prop(n, "Parent")
        hops = hops + 1
    end
    return nil
end

