        out("tags: " .. #tags)
        for i, tag in ipairs(tags) do
            if i > 400 then
                out("... +" .. (#tags - 400) .. " more tags")
                break
            end
            local okG, list = pcall(CollectionService.GetTagged, CollectionService, tag)
            local cnt = (okG and type(list) == "table") and #list or 0
            local samples = {}
            for j = 1, math.min(3, cnt) do
                samples[#samples + 1] = fullName(list[j]) .. ownerSuffix(list[j])
            end
            out("tag " .. tostring(tag) .. " x" .. cnt .. ": " .. table.concat(samples, " | "))
        end
