    end },

    { "getgc", "GETGC PROBE (tables with role/team/players keys)", function(out)
        if type(getgc) ~= "function" then
            out("getgc: not available")
            return
        end
        local list = getgc(true)
        if type(list) ~= "table" then
            out("getgc returned " .. typeof(list))
            return
        end
        local pset = {}
        for _, p in ipairs(Players:GetPlayers()) do
            pset[p] = true
            pset[pname(p)] = true
            local uid = prop(p, "UserId")
            if type(uid) == "number" and uid > 100 then
                pset[uid] = true
            end
        end
        local t0 = os.clock()
        local hits, phits, scanned = {}, {}, 0
        local total = #list
        for i = 1, math.min(total, 200000) do
            local o = list[i]
            scanned = i
            if type(o) == "table" and not OWN[o] then
                local matched = nil
                for _, k in ipairs(GC_KEYS) do
                    if rawget(o, k) ~= nil then
                        matched = matched or {}
                        matched[#matched + 1] = k
                    end
                end
                if matched then
                    if #hits < 200 then
                        hits[#hits + 1] = { o, matched }
                    end
                elseif #phits < 50 then
                    local c = 0
                    for k in next, o do
                        c = c + 1
                        if c > 16 then
                            break
                        end
                        if pset[k] then
                            phits[#phits + 1] = { o, k }
                            break
                        end
                    end
                end
            end
            if i % 2000 == 0 and os.clock() - t0 > 2 then
                out("time cap (2s) reached")
                break
            end
        end
        out("gc objects: " .. total .. ", scanned: " .. scanned .. ", key hits: " .. #hits .. ", player-keyed: " .. #phits)
        table.sort(hits, function(a, b)
            return #a[2] > #b[2]
        end)
        for i = 1, math.min(25, #hits) do
            local h = hits[i]
            out("#" .. i .. " keys[" .. table.concat(h[2], ",") .. "] " .. flatTable(h[1], 30))
        end
        for i = 1, math.min(15, #phits) do
            local h = phits[i]
            out("P" .. i .. " keyed by " .. (fmtv(h[2]) or "?") .. ": " .. flatTable(h[1], 20))
        end
